		fConst10 = 1.0f - fConst9;
		fConst11 = std::exp(0.0f - 1250.0f / fConst0);
		fConst12 = std::exp(0.0f - 4.0f / fConst0);
		fConst13 = 1.0f - fConst12;
		fConst14 = std::exp(0.0f - 1.0f / fConst0);
