	static mydsp* create() {
		mydsp* dsp = new (fManager->allocate(sizeof(mydsp))) mydsp();
		dsp->memoryCreate();
		return dsp;
	}
	
	static void destroy(dsp* dsp) {
		static_cast<mydsp*>(dsp)->memoryDestroy();
		fManager->destroy(dsp);
	}

